algorithms.pseudocode:
def canonical(method, host, path, exp, claims):
    p = normalize_path(path)            # percent-encoding, no '..', lowercase host
    items = sorted(claims.items())      # deterministic order
    return '\n'.join([method, host.lower(), p, f'exp={exp}'] +
                     [f'{k}={v}' for k, v in items]).encode()

def sign(path, ttl, claims, key):
    exp = now_server() + ttl
    mac = hmac_sha256(key.secret, canonical('GET', HOST, path, exp, claims))
    return {'exp': exp, 'kid': key.kid, **claims, 'sig': b64url(mac[:16])}

def verify(req):
    key = edge_kv.get('key:' + req.q.kid)
    if key is None or key.state == 'retired': return DENY('bad_kid')
    exp = int(req.q.exp)
    if now_edge() > exp + SKEW_S: return DENY('expired')
    claims = {k: req.q[k] for k in SIGNED_CLAIMS if k in req.q}
    mac = hmac_sha256(key.secret, canonical(req.method, req.host, req.path, exp, claims))
    if not const_time_eq(b64url(mac[:16]), req.q.sig): return DENY('bad_sig')
    if int(claims.get('ep', 0)) < edge_kv.get_epoch(claims.get('uid')): return DENY('revoked')
    return ALLOW

def bucketed_exp(ttl, bucket=300):
    t = now_server()
    return ((t + ttl) // bucket + 1) * bucket   # lifetime in [ttl, ttl+bucket)
